-- Plan 37 (Poker hỗn loạn): the GM's per-card rules (on/off, draw weight, a date window), the chaos settings as key →
-- JSON, and `games.chaos_used` for the "Thẻ đã dùng" line of the hand history.
-- Generated by `pnpm --filter @bp/normal-server db:generate --name chaos`, then guarded with IF NOT EXISTS in
-- `0006_plan27.sql`'s style, so a second run is a no-op. Additive: two new tables and one nullable column; no seed (a
-- card with no rule follows `data/chaos-cards.json`, and no `chaos` config row means the defaults of `@bp/core`).
-- The configuration tables' `updated_by` carries no foreign key on purpose (see `schema.ts`).
CREATE TABLE IF NOT EXISTS "chaos_card_rules" (
	"card_id" text PRIMARY KEY NOT NULL,
	"enabled" boolean NOT NULL,
	"weight" integer DEFAULT 1 NOT NULL,
	"starts_at" timestamp with time zone,
	"ends_at" timestamp with time zone,
	"updated_by" uuid,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chaos_card_rules_weight_range" CHECK ("chaos_card_rules"."weight" BETWEEN 0 AND 100)
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "chaos_config" (
	"key" text PRIMARY KEY NOT NULL,
	"value" jsonb NOT NULL,
	"updated_by" uuid,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "games" ADD COLUMN IF NOT EXISTS "chaos_used" jsonb;
